<!doctype html>
<html lang="fa" dir="rtl">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>درگاه دانشجویی هم‌قدم</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap');
*{box-sizing:border-box}body{margin:0;background:#f3f7f5;color:#18352f;font-family:Vazirmatn,Tahoma,sans-serif}header{background:#fff;padding:18px 5%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e5ece8;position:sticky;top:0;z-index:5}h1{font-size:18px;margin:0}.wrap{max-width:1150px;margin:28px auto;padding:0 16px}.card{background:white;border:1px solid #e5ece8;border-radius:16px;padding:20px;margin-bottom:16px}h2{font-size:18px;margin:0 0 16px}h3{font-size:15px;margin:18px 0 10px}label{display:block;font-size:12px;font-weight:700;color:#536c63;margin:8px 0}input,select,textarea{width:100%;padding:11px;border:1px solid #d8e3dd;border-radius:9px;font:inherit;margin:4px 0 12px}button{border:0;border-radius:9px;background:#16745e;color:white;padding:10px 15px;font:inherit;cursor:pointer}button.secondary{background:#eaf1ed;color:#35574d}button.danger{background:#fff0ef;color:#a33b35}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.event{border:1px solid #e8efeb;padding:14px;border-radius:12px;margin:9px 0}.muted{color:#82938b;font-size:12px}.msg{padding:10px;border-radius:8px;background:#edf7f1;margin:10px 0}.error{background:#fff0ef;color:#a33b35}.hidden{display:none!important}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.tabs button.active{background:#124d40}table{width:100%;border-collapse:collapse}td,th{text-align:right;padding:10px;border-bottom:1px solid #edf1ee;font-size:12px}.tablewrap{overflow:auto}.badge{background:#edf4f0;border-radius:20px;padding:4px 8px;font-size:11px}.profile-progress{margin:14px 0 20px;padding:14px;border:1px solid #e5ece8;border-radius:12px;background:#fbfdfb}.profile-progress-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:9px;font-size:13px;font-weight:700}.profile-progress-track{height:10px;background:#e8efeb;border-radius:20px;overflow:hidden}.profile-progress-bar{height:100%;width:0;background:#16836b;border-radius:20px;transition:width .25s ease}.profile-progress-meta{display:flex;justify-content:space-between;gap:10px;margin-top:8px;font-size:11px;color:#82938b}.profile-progress-hint{font-size:11px;color:#536c63;margin-top:8px}.student-loader{position:fixed;inset:0;background:#ffffffdf;z-index:999;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:14px}.student-loader .track{width:min(260px,75vw);height:6px;background:#e4ece9;border-radius:8px;overflow:hidden}.student-loader .bar{height:100%;width:35%;background:#16836b;border-radius:8px;animation:studentProgress 1.1s ease-in-out infinite}@keyframes studentProgress{0%{transform:translateX(220%)}100%{transform:translateX(-320%)}}.jalali-picker{position:fixed;z-index:1001;width:290px;background:#fff;border:1px solid #dce7e1;border-radius:13px;padding:12px;box-shadow:0 12px 40px #17382d25}.jp-head,.jp-foot{display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:10px}.jp-head button,.jp-foot button{font-size:11px;padding:6px 8px}.jp-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;text-align:center}.jp-grid span{font-size:11px;color:#82938b;padding:5px}.jp-grid button{padding:7px 2px;background:#f0f5f2;color:#23483c;font-size:12px}.jp-grid button.selected{background:#16745e;color:#fff}.jp-grid i{min-height:30px}.jp-foot{margin:10px 0 0}@media(max-width:600px){header{padding:14px}.card{padding:15px}}
</style></head>
<body>
<header><h1>🤝 درگاه دانشجویی هم‌قدم</h1><div class="row"><span id="studentName" class="muted"></span><button id="logoutBtn" class="secondary hidden" onclick="logout()">خروج</button></div></header>
<div id="studentLoader" class="student-loader hidden"><div style="font-size:28px">🤝</div><div class="track"><div class="bar"></div></div><div id="studentLoaderText" class="muted">در حال انجام عملیات...</div></div><div class="wrap">
<section id="loginCard" class="card" style="max-width:460px;margin:7vh auto"><h2>ورود دانشجو</h2><label>ایمیل</label><input id="email" type="email"><label>رمز عبور</label><input id="password" type="password"><button onclick="login()">ورود</button><div id="loginMsg"></div><p class="muted">برای دریافت حساب کاربری با مدیر فرهنگی دانشگاه خود تماس بگیرید.</p></section>
<section id="portal" class="hidden">
<div class="tabs"><button class="active" data-tab="profile">اطلاعات دانشجویی</button><button data-tab="events">برنامه‌های فرهنگی</button><button data-tab="records">سوابق فرهنگی</button><button data-tab="registrations">ثبت‌نام‌های من</button><button data-tab="notifications">اعلان‌ها</button></div>
<section id="profile" class="card"><h2>اطلاعات دانشجویی</h2><div id="studentStatus" class="muted"></div><div class="profile-progress" aria-live="polite"><div class="profile-progress-head"><span>میزان تکمیل اطلاعات دانشجویی</span><strong id="profileProgressPercent">۰٪</strong></div><div class="profile-progress-track" role="progressbar" aria-label="درصد تکمیل پروفایل" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" id="profileProgressTrack"><div class="profile-progress-bar" id="profileProgressBar"></div></div><div class="profile-progress-meta"><span id="profileProgressCount">۰ از ۵ مورد تکمیل شده</span><span id="profileProgressStatus">در انتظار تکمیل</span></div><div class="profile-progress-hint" id="profileProgressHint">برای تکمیل پروفایل، دانشگاه، شماره دانشجویی، رشته، مقطع و سال ورود را وارد کنید.</div></div><div class="grid"><div><label>دانشگاه</label><select id="university"></select></div><div><label>شماره دانشجویی</label><input id="studentNumber"></div><div><label>رشته تحصیلی</label><input id="field"></div><div><label>مقطع</label><select id="degree"><option value="">انتخاب کنید</option><option>کاردانی</option><option>کارشناسی</option><option>کارشناسی ارشد</option><option>دکتری</option></select></div><div><label>سال ورود شمسی</label><input id="entryYear" type="number" min="1300" max="1500"></div><h3>عضویت‌ها و فعالیت‌های فرهنگی (برای بررسی مدیر)</h3><div class="grid" id="membershipOptions"><label><input type="checkbox" class="membership" value="basij" style="width:auto"> عضویت در بسیج دانشجویی</label><label><input type="checkbox" class="membership" value="islamic_association" style="width:auto"> عضویت در انجمن اسلامی</label><label><input type="checkbox" class="membership" value="student_council" style="width:auto"> عضویت در شورای صنفی</label><label><input type="checkbox" class="membership" value="cultural_active" style="width:auto"> فعال فرهنگی</label><label><input type="checkbox" class="membership" value="cultural_representative" style="width:auto"> رابط فرهنگی</label></div><button onclick="saveStudent()">ذخیره اطلاعات</button><div id="profileMsg"></div></section>
<section id="events" class="card hidden"><h2>برنامه‌های منتشرشده</h2><div id="eventsList">در حال بارگذاری...</div><div id="studentAlbums"></div><div class="card"><h3>پیوستن به گروه با کد دعوت</h3><input id="inviteCode" placeholder="کد دعوت گروه"><button onclick="joinGroup()">عضویت در گروه</button><div id="groupMsg"></div></div></section>
<section id="records" class="card hidden"><h2>سوابق و فعالیت‌های فرهنگی</h2><p class="muted">سوابق ثبت‌شده پس از بررسی مدیر فرهنگی در محاسبه ضریب قرعه‌کشی برنامه‌های مرتبط قابل استفاده خواهند بود.</p><div class="grid"><div><label>نوع سابقه</label><select id="recordType"><option value="cultural_activity">فعالیت فرهنگی</option><option value="organization_membership">عضویت در تشکل</option><option value="volunteer">فعالیت داوطلبانه</option><option value="award">تقدیر و جایزه</option><option value="other">سایر</option></select></div><div><label>عنوان</label><input id="recordTitle" placeholder="عنوان فعالیت یا تشکل"></div><div><label>نام تشکل / برگزارکننده</label><input id="organizationName"></div></div><label>توضیحات</label><textarea id="recordDescription" rows="3"></textarea><div class="grid"><div><label>تاریخ شروع</label><input id="recordStart" class="jalali-date" type="text" autocomplete="off" readonly></div><div><label>تاریخ پایان</label><input id="recordEnd" class="jalali-date" type="text" autocomplete="off" readonly></div></div><button onclick="submitRecord()">ارسال سابقه برای تأیید</button><div id="recordMsg"></div><h3>سوابق ثبت‌شده</h3><div id="recordsList"></div></section>
<section id="registrations" class="card hidden"><h2>ثبت‌نام‌های من</h2><div id="registrationsList"></div><h3>گروه‌های من</h3><div id="groupsList"></div></section>
<section id="notifications" class="card hidden"><h2>اعلان‌ها</h2><div id="notificationsList"></div></section>
</section></div>
<script>
const API='/api/v1';let token=localStorage.getItem('hg_student_token')||'';const $=id=>document.getElementById(id);const auth=()=>({'Accept':'application/json','Authorization':'Bearer '+token});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function show(id,msg,bad=false){$(id).innerHTML='<div class="msg '+(bad?'error':'')+'">'+esc(msg)+'</div>'}
let studentLoaderDepth=0;function showStudentLoader(t){studentLoaderDepth++;$('studentLoaderText').textContent=t||'در حال انجام عملیات...';$('studentLoader').classList.remove('hidden')}function hideStudentLoader(){studentLoaderDepth=Math.max(0,studentLoaderDepth-1);if(!studentLoaderDepth)$('studentLoader').classList.add('hidden')}
async function api(path,opt={}){showStudentLoader('در حال دریافت یا ذخیره اطلاعات...');try{const headers={...auth(),...(opt.headers||{})};if(opt.body&&!(opt.body instanceof FormData))headers['Content-Type']='application/json';const res=await fetch(API+path,{...opt,headers});const data=await res.json().catch(()=>({}));if(!res.ok){const errors=data.errors?Object.values(data.errors).flat().join(' | '):'';throw Error(data.message||errors||('خطای سرور '+res.status))}return data}finally{hideStudentLoader()}}
const jalaliIntl=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'numeric',day:'numeric',timeZone:'UTC'});
function normalizeDigits(v){return String(v||'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d))}
function jalaliParts(date){const a=jalaliIntl.formatToParts(date);const g=k=>Number(a.find(x=>x.type===k)?.value||0);return {year:g('year'),month:g('month'),day:g('day')}}
function jalaliMonthDays(y,m){const start=new Date(Date.UTC(y+621,2,18)),out=[];for(let i=0;i<370;i++){const d=new Date(start.getTime()+i*86400000),p=jalaliParts(d);if(p.year===y&&p.month===m)out.push({date:d,day:p.day})}return out}
function gregorianIso(d){return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`}
function jalaliToGregorian(v){const m=normalizeDigits(v).match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);if(!m)throw Error('تاریخ را از تقویم شمسی انتخاب کنید.');const a=jalaliMonthDays(+m[1],+m[2]).find(x=>x.day===+m[3]);if(!a)throw Error('تاریخ شمسی معتبر نیست.');return gregorianIso(a.date)}
function gregorianToJalali(v){if(!v)return '';const m=String(v).match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return '';const p=jalaliParts(new Date(Date.UTC(+m[1],+m[2]-1,+m[3])));return `${p.year}/${String(p.month).padStart(2,'0')}/${String(p.day).padStart(2,'0')}`}
let activeJalaliInput=null,activeJalaliMonth=null;function closeJalaliPicker(){document.getElementById('jalaliPicker')?.remove();activeJalaliInput=null}
function renderJalaliPicker(){if(!activeJalaliInput)return;let p=document.getElementById('jalaliPicker');if(!p){p=document.createElement('div');p.id='jalaliPicker';p.className='jalali-picker';document.body.appendChild(p)}const {year,month}=activeJalaliMonth,names=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'],days=jalaliMonthDays(year,month),offset=(days[0].date.getUTCDay()+1)%7,sel=normalizeDigits(activeJalaliInput.value).match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);let h=`<div class="jp-head"><button type="button" onclick="shiftJalaliMonth(-1)">ماه قبل</button><b>${names[month-1]} ${year}</b><button type="button" onclick="shiftJalaliMonth(1)">ماه بعد</button></div><div class="jp-grid">${['ش','ی','د','س','چ','پ','ج'].map(x=>`<span>${x}</span>`).join('')}`;for(let i=0;i<offset;i++)h+='<i></i>';for(const x of days)h+=`<button type="button" class="${sel&&+sel[1]===year&&+sel[2]===month&&+sel[3]===x.day?'selected':''}" onclick="chooseJalaliDate(${year},${month},${x.day})">${x.day}</button>`;p.innerHTML=h+'</div><div class="jp-foot"><button type="button" onclick="chooseTodayJalali()">امروز</button><button type="button" onclick="closeJalaliPicker()">بستن</button></div>';const r=activeJalaliInput.getBoundingClientRect();p.style.top=Math.min(r.bottom+5,innerHeight-320)+'px';p.style.left=Math.max(8,Math.min(r.left,innerWidth-298))+'px'}
function shiftJalaliMonth(d){let y=activeJalaliMonth.year,m=activeJalaliMonth.month+d;if(m<1){m=12;y--}if(m>12){m=1;y++}activeJalaliMonth={year:y,month:m};renderJalaliPicker()}
function chooseJalaliDate(y,m,d){activeJalaliInput.value=`${y}/${String(m).padStart(2,'0')}/${String(d).padStart(2,'0')}`;closeJalaliPicker()}
function chooseTodayJalali(){const n=new Date(),p=jalaliParts(new Date(Date.UTC(n.getFullYear(),n.getMonth(),n.getDate())));chooseJalaliDate(p.year,p.month,p.day)}
function openJalaliPicker(input){activeJalaliInput=input;const m=normalizeDigits(input.value).match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/),p=m?{year:+m[1],month:+m[2]}:jalaliParts(new Date());activeJalaliMonth={year:p.year,month:p.month};renderJalaliPicker()}
function initJalaliPickers(){document.querySelectorAll('.jalali-date').forEach(i=>{i.readOnly=true;i.placeholder='برای انتخاب تاریخ کلیک کنید';i.onclick=()=>openJalaliPicker(i)});if(!window.studentJalaliBound){document.addEventListener('click',e=>{if(!e.target.closest('.jalali-picker')&&!e.target.closest('.jalali-date'))closeJalaliPicker()});window.addEventListener('resize',closeJalaliPicker);window.studentJalaliBound=true}}
async function login(){try{const d=await api('/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('email').value,password:$('password').value})});token=d.token;localStorage.setItem('hg_student_token',token);await boot()}catch(e){show('loginMsg',e.message,true)}}
function logout(){localStorage.removeItem('hg_student_token');token='';$('portal').classList.add('hidden');$('loginCard').classList.remove('hidden');$('logoutBtn').classList.add('hidden')}
async function boot(){try{const p=await api('/profile');$('studentName').textContent=p.user?.name||'';$('loginCard').classList.add('hidden');$('portal').classList.remove('hidden');$('logoutBtn').classList.remove('hidden');await loadUniversities();await loadStudent();await loadEvents();await loadRecords();await loadRegistrations();await loadNotifications()}catch(e){logout();show('loginMsg',e.message,true)}}
async function loadUniversities(){const d=await api('/universities');const list=d.data||[];$('university').innerHTML='<option value="">انتخاب دانشگاه</option>'+list.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}
async function loadStudent(){const d=await api('/student');const s=d.student;if(s){$('university').value=s.university_id;$('studentNumber').value=s.student_number||'';$('field').value=s.field_of_study||'';$('degree').value=s.degree||'';$('entryYear').value=s.entry_year||'';const chosen=(s.user?.student_cultural_records||[]).filter(r=>r.record_type==='organization_membership').map(r=>r.title);const membershipMap={'عضویت در بسیج دانشجویی':'basij','عضویت در انجمن اسلامی':'islamic_association','عضویت در شورای صنفی':'student_council','فعال فرهنگی':'cultural_active','رابط فرهنگی':'cultural_representative'};document.querySelectorAll('.membership').forEach(c=>c.checked=chosen.includes(Object.keys(membershipMap).find(k=>membershipMap[k]===c.value)));$('studentStatus').textContent='وضعیت تأیید پروفایل: '+({active:'تأیید شده',pending:'در انتظار بررسی',rejected:'رد شده'}[s.status]||s.status);updateProfileProgress()}else{$('studentStatus').textContent='هنوز اطلاعات دانشجویی ثبت نشده است.';updateProfileProgress()}}
function updateProfileProgress(){const fields=[!!$('university').value,!!$('studentNumber').value.trim(),!!$('field').value.trim(),!!$('degree').value,!!$('entryYear').value];const done=fields.filter(Boolean).length;const percent=Math.round(done/fields.length*100);$('profileProgressPercent').textContent=percent.toLocaleString('fa-IR')+'٪';$('profileProgressCount').textContent=done.toLocaleString('fa-IR')+' از '+fields.length.toLocaleString('fa-IR')+' مورد تکمیل شده';$('profileProgressBar').style.width=percent+'%';$('profileProgressTrack').setAttribute('aria-valuenow',String(percent));$('profileProgressStatus').textContent=percent===100?'اطلاعات کامل است':percent===0?'در انتظار تکمیل':'در حال تکمیل';$('profileProgressHint').textContent=percent===100?'اطلاعات اصلی کامل شد؛ پس از ذخیره، وضعیت تأیید مدیر را پیگیری کنید.':'فیلدهای باقی‌مانده را تکمیل کنید؛ عضویت‌ها و فعالیت‌های فرهنگی جداگانه برای بررسی مدیر ارسال می‌شوند.'}
async function saveStudent(){try{updateProfileProgress();await api('/student',{method:'POST',body:JSON.stringify({university_id:+$('university').value,student_number:$('studentNumber').value,field_of_study:$('field').value,degree:$('degree').value,entry_year:$('entryYear').value?+$('entryYear').value:null,memberships:[...document.querySelectorAll('.membership:checked')].map(x=>x.value)})});show('profileMsg','اطلاعات ذخیره شد و برای تأیید مدیر ارسال شد.');await loadStudent()}catch(e){show('profileMsg',e.message,true)}}
async function loadEvents(){try{const d=await api('/events');$('eventsList').innerHTML=(d.data||[]).map(e=>`<div class="event"><b>${esc(e.title)}</b><p class="muted">${esc(e.university?.name||'')} | ${esc(e.category||'')} | ظرفیت ${e.capacity}</p><p>${esc(e.description||'')}</p><div class="row"><button onclick="registerEvent(${e.id})">ثبت‌نام انفرادی</button>${e.is_group_registration_allowed?`<button class="secondary" onclick="createGroup(${e.id})">ایجاد گروه</button>`:''}<button class="secondary" onclick="viewAlbums(${e.id})">آلبوم تصاویر</button></div></div>`).join('')||'برنامه منتشرشده‌ای وجود ندارد.'}catch(e){$('eventsList').textContent=e.message}}
async function viewAlbums(id){try{const d=await api(`/events/${id}/albums`);const albums=d.albums?.data||d.albums||[];$('studentAlbums').innerHTML=albums.length?`<div class="card"><h3>آلبوم تصاویر</h3>${albums.map(a=>`<h4>${esc(a.title)}</h4><div class="grid">${(a.media||[]).map(m=>`<div><img src="${esc(m.url||('/storage/'+m.file_path))}" style="width:100%;border-radius:10px"><p class="muted">${esc(m.caption||'')}</p></div>`).join('')}</div>`).join('')}</div>`:'آلبومی برای نمایش وجود ندارد.'}catch(e){$('studentAlbums').textContent=e.message}}
async function registerEvent(id){try{const d=await api(`/events/${id}/register`,{method:'POST'});alert(d.message||'درخواست ثبت شد.');await loadRegistrations()}catch(e){alert(e.message)}}
async function createGroup(id){const name=prompt('نام گروه را وارد کنید:');if(!name)return;try{const d=await api(`/events/${id}/groups`,{method:'POST',body:JSON.stringify({name})});alert((d.message||'گروه ایجاد شد.')+'\nکد دعوت: '+d.group.invite_code);await loadRegistrations()}catch(e){alert(e.message)}}
async function joinGroup(){try{const d=await api('/groups/join',{method:'POST',body:JSON.stringify({invite_code:$('inviteCode').value})});show('groupMsg',d.message);$('inviteCode').value='';await loadRegistrations()}catch(e){show('groupMsg',e.message,true)}}
async function loadRecords(){try{const d=await api('/student/cultural-records');$('recordsList').innerHTML=(d.records||[]).map(r=>`<div class="event"><b>${esc(r.title)}</b> <span class="badge">${esc(({pending:'در انتظار بررسی',verified:'تأیید شده',rejected:'رد شده'})[r.status]||r.status)}</span><p class="muted">${esc(r.organization_name||'')} | ${esc(r.record_type)}</p><p>${esc(r.description||'')}</p>${r.review_note?`<small>${esc(r.review_note)}</small>`:''}</div>`).join('')||'سابقه‌ای ثبت نشده است.'}catch(e){$('recordsList').textContent=e.message}}
async function submitRecord(){try{const d=await api('/student/cultural-records',{method:'POST',body:JSON.stringify({record_type:$('recordType').value,title:$('recordTitle').value,organization_name:$('organizationName').value,description:$('recordDescription').value,started_on:$('recordStart').value?jalaliToGregorian($('recordStart').value):null,ended_on:$('recordEnd').value?jalaliToGregorian($('recordEnd').value):null})});show('recordMsg',d.message);$('recordTitle').value='';$('organizationName').value='';$('recordDescription').value='';await loadRecords()}catch(e){show('recordMsg',e.message,true)}}
async function loadRegistrations(){try{const d=await api('/my-registrations');const rows=d.data||[];$('registrationsList').innerHTML=rows.map(r=>`<div class="event"><b>${esc(r.event?.title||'برنامه')}</b><span class="badge">${esc(({pending:'در انتظار قرعه‌کشی/بررسی',pending_approval:'منتظر تأیید مدیر',confirmed:'تأیید شده',waitlisted:'فهرست انتظار',cancelled:'لغو شده',rejected:'رد شده'})[r.status]||r.status)}</span>${!['cancelled','rejected'].includes(r.status)?` <button class="danger" onclick="cancelRegistration(${r.id})">لغو ثبت‌نام</button>`:''}${r.event?.status==='completed'&&r.status==='confirmed'?`<div class="grid"><div><label>امتیاز رضایت</label><select id="rating-${r.event_id}"><option value="5">۵ - عالی</option><option value="4">۴ - خوب</option><option value="3">۳ - متوسط</option><option value="2">۲ - ضعیف</option><option value="1">۱ - بسیار ضعیف</option></select></div><div><label>نظر</label><input id="comment-${r.event_id}" placeholder="نظر شما درباره برنامه"></div></div><button class="secondary" onclick="sendFeedback(${r.event_id})">ثبت بازخورد</button>`:''}</div>`).join('')||'ثبت‌نامی ندارید.';const g=await api('/my-groups');$('groupsList').innerHTML=(g.groups||[]).map(x=>`<div class="event"><b>${esc(x.name)}</b> - ${esc(x.event?.title||'')}<p class="muted">کد دعوت: ${esc(x.invite_code)} | اعضا: ${(x.registrations||[]).length}/${x.max_members}</p></div>`).join('')||'عضو گروهی نیستید.'}catch(e){$('registrationsList').textContent=e.message}}
async function sendFeedback(eventId){try{const d=await api(`/events/${eventId}/feedback`,{method:'POST',body:JSON.stringify({rating:+$('rating-'+eventId).value,comment:$('comment-'+eventId).value,is_anonymous:false})});alert(d.message||'بازخورد ثبت شد.')}catch(e){alert(e.message)}}
async function cancelRegistration(id){if(!confirm('ثبت‌نام لغو شود؟'))return;try{await api('/registrations/'+id,{method:'DELETE'});await loadRegistrations()}catch(e){alert(e.message)}}
async function loadNotifications(){try{const d=await api('/notifications');$('notificationsList').innerHTML=(d.notifications?.data||[]).map(n=>{const x=n.data||{};return `<div class="event"><b>${esc(x.title||'اعلان')}</b><p>${esc(x.body||'')}</p><small class="muted">${esc(n.created_at||'')}</small></div>`}).join('')||'اعلانی ندارید.'}catch(e){$('notificationsList').textContent=e.message}}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));['profile','events','records','registrations','notifications'].forEach(id=>$(id).classList.toggle('hidden',id!==b.dataset.tab))});
['university','studentNumber','field','degree','entryYear'].forEach(id=>{const el=$(id);el.addEventListener('input',updateProfileProgress);el.addEventListener('change',updateProfileProgress)});document.querySelectorAll('.membership').forEach(el=>el.addEventListener('change',updateProfileProgress));updateProfileProgress();initJalaliPickers();if(token)boot();
</script></body></html>
